import React from 'react';

const ClienteList = ({ clientes, setSelectedClienteId }) => {

  const handleClienteClick = (id) => {
    setSelectedClienteId(id);  // Setando o ID do cliente ao clicar
  };

  return (
    <div className="clientes-list">
      {clientes.length > 0 ? (
        clientes.map(cliente => (
          <div
            key={cliente.id}
            className="cliente-card"
            onClick={() => handleClienteClick(cliente.id)}  // Função ao clicar no card
          >
            <h3>{cliente.nome}</h3>
            <p>{cliente.email}</p>
            <p>{cliente.telefone}</p>
            <button>Ver Projetos</button>  {/* Botão de interação */}
          </div>
        ))
      ) : (
        <p>Nenhum cliente encontrado.</p>  // Caso não haja clientes
      )}
    </div>
  );
};

export default ClienteList;
